// frontend/src/App.js

import React, { useState, useEffect, useRef } from 'react';
import './App.css'; // We'll update this next

function App() {
  // State to store chat messages
  const [messages, setMessages] = useState([]);
  // State for the current message being typed by the user
  const [input, setInput] = useState('');
  // State to store the session ID for persistent chats
  const [sessionId, setSessionId] = useState(null);

  // Ref for auto-scrolling to the bottom of the chat window
  const messagesEndRef = useRef(null);

  // Effect to scroll to the bottom when messages update
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Effect to initialize session ID from local storage on component mount
  useEffect(() => {
    const storedSessionId = localStorage.getItem('chatSessionId');
    if (storedSessionId) {
      setSessionId(storedSessionId);
      // Optional: Fetch previous chat history if you implement that API in Django
      // For now, we'll start fresh with the retrieved session ID
    } else {
      // If no session ID, it will be generated by Django on the first request
      console.log("No session ID found in local storage. Django will generate one.");
    }
  }, []); // Empty dependency array means this runs once on mount

  const sendMessage = async () => {
    if (input.trim() === '') return;

    const userMessage = { sender: 'user', text: input };
    setMessages((prevMessages) => [...prevMessages, userMessage]);
    setInput(''); // Clear the input field

    try {
      const payload = { message: input };
      if (sessionId) {
        payload.session_id = sessionId; // Include session ID if available
      }

      const response = await fetch('/api/chat/', { // Using the proxy for /api/
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      const botMessage = { sender: 'bot', text: data.reply }; // 'reply' is the key from your Django response

      // Update session ID if it was generated/returned by Django
      if (data.session_id && data.session_id !== sessionId) {
        setSessionId(data.session_id);
        localStorage.setItem('chatSessionId', data.session_id);
        console.log("New session ID stored:", data.session_id);
      }

      setMessages((prevMessages) => [...prevMessages, botMessage]);

    } catch (error) {
      console.error("Error sending message:", error);
      setMessages((prevMessages) => [...prevMessages, { sender: 'bot', text: "Sorry, I'm having trouble connecting right now. Please try again." }]);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>Travel Assistant Chatbot</h1>
      </header>
      <div className="chat-window">
        {messages.length === 0 && (
          <div className="welcome-message message bot">
            Hello! I'm your travel assistant. How can I help you plan your next adventure?
          </div>
        )}
        {messages.map((msg, index) => (
          <div key={index} className={`message ${msg.sender}`}>
            {msg.text.split('\n').map((line, i) => ( // Render newlines
              <React.Fragment key={i}>
                {line}
                <br />
              </React.Fragment>
            ))}
          </div>
        ))}
        <div ref={messagesEndRef} /> {/* Scroll target */}
      </div>
      <div className="message-input-container">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={(e) => {
            if (e.key === 'Enter') {
              sendMessage();
            }
          }}
          placeholder="Ask me about destinations, weather, or attractions..."
          className="message-input"
        />
        <button onClick={sendMessage} className="send-button">Send</button>
      </div>
    </div>
  );
}

export default App;
